content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: #0b0b1a;
  color: #f0f0f5;
  overflow: hidden;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  background: radial-gradient(circle at center, #1b1b3a 0%, #05050f 100%);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.control-panel {
  position: absolute;
  top: 20px;
  left: 20px;
  width: 320px;
  background: rgba(15, 15, 30, 0.85);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 20px;
  z-index: 10;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-height: calc(100vh - 40px);
  overflow-y: auto;
}

.info-panel {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 320px;
  background: rgba(15, 15, 30, 0.85);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 20px;
  z-index: 10;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.title {
  font-size: 1.25rem;
  font-weight: bold;
  color: #fff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
  letter-spacing: 0.05em;
}

.slider-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.slider-group label {
  font-size: 0.9rem;
  color: #ccc;
  display: flex;
  justify-content: space-between;
}

.slider-group input[type="range"] {
  width: 100%;
  accent-color: #4f46e5;
  cursor: pointer;
}

.btn {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 10px 16px;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 500;
  transition: all 0.2s ease;
  text-align: center;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.2);
}

.btn-primary {
  background: #4f46e5;
  color: #fff;
  border: none;
  padding: 10px 16px;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 500;
  transition: all 0.2s ease;
  text-align: center;
}

.btn-primary:hover {
  background: #4338ca;
}

/* スクロールバーのカスタム */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

export interface Planet {
  id: string;
  name: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
  description: string;
}

export interface ControlPanelProps {
  speed: number;
  onSpeedChange: (speed: number) => void;
  selectedPlanet: string | null;
  onSelectPlanet: (id: string | null) => void;
  showOrbits: boolean;
  onToggleOrbits: () => void;
  planets: Planet[];
}

export interface SolarSystemProps {
  planets: Planet[];
  speed: number;
  selectedPlanet: string | null;
  showOrbits: boolean;
  onSelectPlanet: (id: string) => void;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { SolarSystemProps } from './types';

export default function SolarSystem({
  planets = [],
  speed = 1,
  selectedPlanet = null,
  showOrbits = true,
  onSelectPlanet,
}: SolarSystemProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const container = containerRef.current;
    const width = container.clientWidth;
    const height = container.clientHeight;

    // シーン、カメラ、レンダラー
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 1000);
    camera.position.set(0, 40, 70);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(window.devicePixelRatio);
    container.appendChild(renderer.domElement);

    // ライティング
    const ambientLight = new THREE.AmbientLight(0x333333);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xffffff, 2, 300);
    scene.add(sunLight);

    // 太陽
    const sunGeometry = new THREE.SphereGeometry(5, 32, 32);
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffcc00 });
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sunMesh);

    // 惑星メッシュと軌道の管理
    const planetMeshes: { [key: string]: THREE.Mesh } = {};
    const orbitLines: { [key: string]: THREE.Line } = {};
    const planetAngles: { [key: string]: number } = {};

    planets.forEach((planet) => {
      planetAngles[planet.id] = Math.random() * Math.PI * 2;

      // 惑星メッシュ
      const geo = new THREE.SphereGeometry(planet.radius, 32, 32);
      const mat = new THREE.MeshStandardMaterial({
        color: planet.color,
        roughness: 0.8,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.userData = { id: planet.id };
      scene.add(mesh);
      planetMeshes[planet.id] = mesh;

      // 軌道
      if (showOrbits) {
        const points = [];
        const segments = 128;
        for (let i = 0; i <= segments; i++) {
          const theta = (i / segments) * Math.PI * 2;
          points.push(
            new THREE.Vector3(
              Math.cos(theta) * planet.distance,
              0,
              Math.sin(theta) * planet.distance
            )
          );
        }
        const orbitGeo = new THREE.BufferGeometry().setFromPoints(points);
        const orbitMat = new THREE.LineBasicMaterial({
          color: 0xffffff,
          transparent: true,
          opacity: 0.15,
        });
        const line = new THREE.Line(orbitGeo, orbitMat);
        scene.add(line);
        orbitLines[planet.id] = line;
      }
    });

    // レイキャスター（クリック検知用）
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: PointerEvent) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const meshes = Object.values(planetMeshes);
      const intersects = raycaster.intersectObjects(meshes);

      if (intersects.length > 0) {
        const intersectedMesh = intersects[0].object as THREE.Mesh;
        const planetId = intersectedMesh.userData.id;
        if (planetId && onSelectPlanet) {
          onSelectPlanet(planetId);
        }
      }
    };

    renderer.domElement.addEventListener('pointerdown', handlePointerDown);

    // リサイズ対応
    const handleResize = () => {
      if (!container) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };

    window.addEventListener('resize', handleResize);

    // アニメーションループ
    let animationFrameId: number;
    let clock = new THREE.Clock();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);
      const delta = clock.getDelta();

      planets.forEach((planet) => {
        const mesh = planetMeshes[planet.id];
        if (mesh) {
          // 公転
          planetAngles[planet.id] += planet.speed * speed * delta * 0.5;
          const angle = planetAngles[planet.id];
          mesh.position.x = Math.cos(angle) * planet.distance;
          mesh.position.z = Math.sin(angle) * planet.distance;

          // 自転
          mesh.rotation.y += delta * speed;
        }
      });

      // 選択された惑星の追従やカメラワークをオプションで行うことも可能
      if (selectedPlanet) {
        const targetMesh = planetMeshes[selectedPlanet];
        if (targetMesh) {
          // カメラを少しターゲットに寄せるなど簡易制御
        }
      }

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      if (renderer.domElement) {
        renderer.domElement.removeEventListener('pointerdown', handlePointerDown);
        container.removeChild(renderer.domElement);
      }
    };
  }, [planets, speed, showOrbits, selectedPlanet, onSelectPlanet]);

  return <div ref={containerRef} className="canvas-container" />;
}

import { ControlPanelProps } from './types';

export default function ControlPanel({
  speed,
  onSpeedChange,
  selectedPlanet,
  onSelectPlanet,
  showOrbits,
  onToggleOrbits,
  planets = [],
}: ControlPanelProps) {
  const currentPlanet = planets.find((p) => p.id === selectedPlanet);

  return (
    <>
      <div className="control-panel">
        <h2 className="title">太陽系シミュレーター</h2>

        <div className="slider-group">
          <label>
            <span>シミュレーション速度</span>
            <span>{speed.toFixed(1)}x</span>
          </label>
          <input
            type="range"
            min="0"
            max="5"
            step="0.1"
            value={speed}
            onChange={(e) => onSpeedChange(parseFloat(e.target.value))}
          />
        </div>

        <button className="btn" onClick={onToggleOrbits}>
          {showOrbits ? '軌道を隠す' : '軌道を表示'}
        </button>

        <div className="slider-group">
          <label>惑星を選択</label>
          <select
            className="btn"
            style={{ width: '100%', textAlign: 'left', background: 'rgba(255, 255, 255, 0.05)' }}
            value={selectedPlanet || ''}
            onChange={(e) => onSelectPlanet(e.target.value || null)}
          >
            <option value="">選択解除（全体表示）</option>
            {planets.map((planet) => (
              <option key={planet.id} value={planet.id} style={{ background: '#1b1b3a', color: '#fff' }}>
                {planet.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {currentPlanet && (
        <div className="info-panel">
          <h2 className="title">{currentPlanet.name}</h2>
          <p style={{ fontSize: '0.9rem', color: '#ccc', lineHeight: '1.5' }}>
            {currentPlanet.description}
          </p>
          <div style={{ fontSize: '0.85rem', color: '#aaa', display: 'flex', flexDirection: 'column', gap: '4px', marginTop: '8px' }}>
            <div>半径: {currentPlanet.radius * 1000} km (スケール)</div>
            <div>太陽からの距離: {currentPlanet.distance * 10} 万km</div>
            <div>公転速度: {(currentPlanet.speed * 10).toFixed(1)} km/s</div>
          </div>
          <button className="btn-primary" style={{ marginTop: '10px' }} onClick={() => onSelectPlanet(null)}>
            閉じる
          </button>
        </div>
      )}
    </>
  );
}

